  'Пальминг': { de: 'Palmieren', es: 'Palming', fr: 'Palming', it: 'Palming', pt: 'Palming', ar: 'تغطية العينين بالكفين', hi: 'पामिंग', ja: 'パーミング', ko: '파밍', zh: '掌敷眼' },
